examples.command:
# If put-bucket-policy succeeds -> ARN is valid (user/role exists)
# If it fails with MalformedPolicy -> IAM principal does not exist
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "AllowUserToListBucket",
    "Effect": "Allow",
    "Resource": "arn:aws:s3:::probe-bucket-12345",
    "Principal": {"AWS": ["arn:aws:iam::<target_account_id>:user/<candidate_username>"]},
    "Action": "s3:ListBucket"
  }]
}

defense.secure_config:
# Avoid account ID in public policies:
# Use Principal: * (public) or reference by service, not account ID

# CloudWatch alarm on AssumeRole failures:
# Metric filter:
# { $.eventName = 'AssumeRole' && $.errorCode = 'AccessDenied' }
# Alarm: > 10 events in 5 minutes → SNS alert

